/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/empty.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Empty({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="empty" className={cn("flex min-w-0 flex-1 flex-col items-center justify-center gap-6 rounded-lg border-dashed p-6 text-center text-balance md:p-12", className)} {...capconsSpread(props)} />;
}
function EmptyHeader({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="empty-header" className={cn("flex max-w-sm flex-col items-center gap-2 text-center", className)} {...capconsSpread(props)} />;
}
const emptyMediaVariants = cva("mb-2 flex shrink-0 items-center justify-center [&_svg]:pointer-events-none [&_svg]:shrink-0", {
  variants: {
    variant: {
      default: "bg-transparent",
      icon: "flex size-10 shrink-0 items-center justify-center rounded-lg bg-muted text-foreground [&_svg:not([class*='size-'])]:size-6"
    }
  },
  defaultVariants: {
    variant: "default"
  }
});
function EmptyMedia({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof emptyMediaVariants> & CapconsBasePropsLoose) {
  return <div data-slot="empty-icon" data-variant={variant} className={cn(emptyMediaVariants({
    variant,
    className
  }))} {...capconsSpread(props)} />;
}
function EmptyTitle({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="empty-title" className={cn("text-lg font-medium tracking-tight", className)} {...capconsSpread(props)} />;
}
function EmptyDescription({
  className,
  ...props
}: React.ComponentProps<"p"> & CapconsBasePropsLoose) {
  return <div data-slot="empty-description" className={cn("text-sm/relaxed text-muted-foreground [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary", className)} {...capconsSpread(props)} />;
}
function EmptyContent({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="empty-content" className={cn("flex w-full max-w-sm min-w-0 flex-col items-center gap-4 text-sm text-balance", className)} {...capconsSpread(props)} />;
}
export { Empty, EmptyHeader, EmptyTitle, EmptyDescription, EmptyContent, EmptyMedia };
